-- ═══════════════════════════════════════════════════════════════════════════
-- 20260814_seed_topology_layout.sql
-- GENERATED by scripts/extract_topology_layout.py — do not hand-edit.
--
-- Geometry lifted verbatim from
-- public/topology_engine/renderer/index.html so the database-driven render
-- is pixel-identical to the hand-drawn original. Any visual difference after
-- the Stage 3 cutover is a bug in the renderer, not a change of design.
--
-- 50 node positions, 52 routed cables.
-- Scoped to the SANDBOX site; production sites are untouched.
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

CREATE TEMP TABLE _layout(equipment_id text PRIMARY KEY, x double precision,
                         y double precision, shape text) ON COMMIT DROP;


UPDATE public.equipment_registry e
   SET layout_x = l.x, layout_y = l.y, render_shape = l.shape
  FROM _layout l
 WHERE e.equipment_id = l.equipment_id
   AND e.site_uuid = (SELECT id FROM public.sites WHERE site_code = 'SANDBOX');

-- The busbar is drawn as a line rather than a cube, so its geometry lives
-- on the node itself.
UPDATE public.equipment_registry
   SET render_path_d = 'M 300 150 L 1700 150'
 WHERE equipment_id = 'node-dg-bus'
   AND site_uuid = (SELECT id FROM public.sites WHERE site_code = 'SANDBOX');

-- ── Room floor plates ─────────────────────────────────────────────────────
CREATE TEMP TABLE _plates(room_name text PRIMARY KEY, label text,
  x double precision, y double precision, w double precision, h double precision,
  lx double precision, ly double precision, fs integer, tint text) ON COMMIT DROP;


UPDATE public.rooms rm
   SET layout_x = p.x, layout_y = p.y, layout_w = p.w, layout_h = p.h,
       layout_label = p.label, label_x = p.lx, label_y = p.ly,
       label_size = p.fs, layout_tint = p.tint
  FROM _plates p
 WHERE rm.room_name = p.room_name
   AND rm.site_id = (SELECT id FROM public.sites WHERE site_code = 'SANDBOX');

-- ── Room assignment follows the drawing ───────────────────────────────────
-- Where a node is DRAWN is surveyed fact; which room it was tagged with is a
-- guess made when the seed was written. So room_id is derived from plate
-- containment, not the other way round. This corrected six nodes on first
-- run, all of them mismatches inherited from the V1 seed.
UPDATE public.equipment_registry e
   SET room_id = rm.id
  FROM public.rooms rm
 WHERE rm.site_id = e.site_uuid
   AND rm.layout_x IS NOT NULL
   AND e.layout_x IS NOT NULL
   AND e.layout_x BETWEEN rm.layout_x AND rm.layout_x + rm.layout_w
   AND e.layout_y BETWEEN rm.layout_y AND rm.layout_y + rm.layout_h
   AND e.site_uuid = (SELECT id FROM public.sites WHERE site_code = 'SANDBOX')
   AND e.room_id IS DISTINCT FROM rm.id;

CREATE TEMP TABLE _paths(render_path_id text PRIMARY KEY, d text) ON COMMIT DROP;


UPDATE public.equipment_connections c
   SET render_path_d = p.d
  FROM _paths p, public.equipment_registry e
 WHERE c.render_path_id = p.render_path_id
   AND e.equipment_id = c.source_equipment_id
   AND e.site_uuid = (SELECT id FROM public.sites WHERE site_code = 'SANDBOX');

-- ── Report what landed, and what did not ──────────────────────────────────
DO $$
DECLARE v_site uuid; v_pos int; v_shape int; v_d int; v_nodrawn int; v_rooms int; v_out int;
BEGIN
  SELECT id INTO v_site FROM public.sites WHERE site_code = 'SANDBOX';
  SELECT count(*) INTO v_pos   FROM public.equipment_registry
   WHERE site_uuid = v_site AND layout_x IS NOT NULL;
  SELECT count(*) INTO v_shape FROM public.equipment_registry
   WHERE site_uuid = v_site AND render_shape IS NOT NULL;
  SELECT count(*) INTO v_d FROM public.equipment_connections c
    JOIN public.equipment_registry e ON e.equipment_id = c.source_equipment_id
   WHERE e.site_uuid = v_site AND c.render_path_d IS NOT NULL;
  SELECT count(*) INTO v_nodrawn FROM public.equipment_registry
   WHERE site_uuid = v_site AND engine_type IS NOT NULL AND layout_x IS NULL;
  SELECT count(*) INTO v_rooms FROM public.rooms
   WHERE site_id = v_site AND layout_x IS NOT NULL;
  SELECT count(*) INTO v_out FROM public.topology_layout_issues
   WHERE site_uuid = v_site;
  RAISE NOTICE 'layout: % positioned, % shaped, % cables routed, % rooms plated, % outside a room',
    v_pos, v_shape, v_d, v_rooms, v_out;
  IF v_nodrawn > 0 THEN
    RAISE EXCEPTION '% simulated node(s) have no coordinates - they would be invisible', v_nodrawn;
  END IF;
END $$;

COMMIT;
